package com.crm.customer;
import com.crm.customer.entity.*;import com.crm.customer.repository.ClientCaseRepository;import com.crm.customer.util.CustomerSpecification;import org.hibernate.SessionFactory;import org.hibernate.cfg.Configuration;import org.junit.jupiter.api.*;import org.springframework.data.jpa.repository.support.SimpleJpaRepository;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.Query;import jakarta.persistence.EntityManager;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Small Hibernate/H2 fixtures only. No SpringBootTest, Flyway or MySQL. */
class CommercialJpaFixtureTest {SessionFactory factory;EntityManager em;SimpleJpaRepository<Customer,Long> customers;Customer acme,other,archived;
 @BeforeEach void setup(){var cfg=new Configuration().addAnnotatedClass(Customer.class).addAnnotatedClass(CustomerInteraction.class).addAnnotatedClass(SalesOpportunity.class).addAnnotatedClass(OpportunityStageHistory.class).addAnnotatedClass(ClientCase.class).addAnnotatedClass(ClientCaseMessage.class).addAnnotatedClass(ClientCaseEvent.class);cfg.setProperty("hibernate.connection.driver_class","org.h2.Driver");cfg.setProperty("hibernate.connection.url","jdbc:h2:mem:commercial_"+UUID.randomUUID()+";MODE=MySQL");cfg.setProperty("hibernate.dialect","org.hibernate.dialect.H2Dialect");cfg.setProperty("hibernate.hbm2ddl.auto","create-drop");cfg.setProperty("hibernate.show_sql","false");factory=cfg.buildSessionFactory();em=factory.createEntityManager();customers=new SimpleJpaRepository<>(Customer.class,em);em.getTransaction().begin();acme=contact("Acme 100%","sales@example.invalid",101L,false,"LEAD","Tech","SMB");other=contact("Other","other@example.invalid",102L,false,"CUSTOMER","Tech","SMB");archived=contact("Archived","old@example.invalid",101L,true,"LEAD","Tech","SMB");em.flush();em.getTransaction().commit();}
 Customer contact(String name,String email,long employee,boolean archive,String type,String category,String segment){var c=new Customer();c.setName(name);c.setEmail(email);c.setAssignedEmployeeId(employee);c.setArchived(archive);c.setContactType(type);c.setCategory(category);c.setSegment(segment);em.persist(c);return c;}
 @AfterEach void close(){if(em!=null){if(em.getTransaction().isActive())em.getTransaction().rollback();em.close();}if(factory!=null)factory.close();}
 @Test void allFiltersAreCombinedInRealJpaCriteriaWithBoundPagination(){var filters=CustomerSpecification.filters("sales@","LEAD"," tech ","smb",101L).and(CustomerSpecification.state("ACTIVE"));var rows=customers.findAll(filters,PageRequest.of(0,1,Sort.by("name").descending()));assertEquals(1,rows.getTotalElements());assertEquals(acme.getId(),rows.getContent().getFirst().getId());assertTrue(customers.findAll(filters,PageRequest.of(1,1)).isEmpty());}
 @Test void archiveAndAssignmentRestrictSeparateRows(){assertEquals(archived.getId(),customers.findAll(CustomerSpecification.filters(null,null,null,null,101L).and(CustomerSpecification.state("ARCHIVED"))).getFirst().getId());assertEquals(1,customers.findAll(CustomerSpecification.filters(null,null,null,null,102L).and(CustomerSpecification.state("ACTIVE"))).size());}
 @Test void wildcardCharactersAreLiteralInUserSearch(){assertEquals(1,customers.findAll(CustomerSpecification.searchByKeyword("%")).size());assertTrue(customers.findAll(CustomerSpecification.searchByKeyword("_")).isEmpty());}
 @Test void archiveKeepsInteractionAndOpportunityIdentityIndependentOfLists(){em.getTransaction().begin();var i=new CustomerInteraction();i.setCustomerId(acme.getId());i.setEmployeeId(101L);i.setInteractionType("CALL");i.setOccurredAt(java.time.LocalDateTime.now());i.setNotes("Private historical");em.persist(i);var opportunity=new SalesOpportunity();opportunity.setCustomerId(acme.getId());opportunity.setTitle("Preserved opportunity");em.persist(opportunity);var event=new OpportunityStageHistory();event.setOpportunityId(opportunity.getId());event.setNewStage("NEW");em.persist(event);acme.setArchived(true);em.flush();em.getTransaction().commit();em.clear();assertNotNull(em.find(Customer.class,acme.getId()));assertEquals(acme.getId(),em.find(CustomerInteraction.class,i.getId()).getCustomerId());assertFalse(em.find(CustomerInteraction.class,i.getId()).isEmployeeVisible());assertEquals(acme.getId(),em.find(SalesOpportunity.class,opportunity.getId()).getCustomerId());assertNotNull(em.find(OpportunityStageHistory.class,event.getId()));}
 @Test void caseQueryBindsOwnerStatusAndNullableAdminScope()throws Exception{em.getTransaction().begin();for(long customer:List.of(acme.getId(),other.getId())){var c=new ClientCase();c.setCustomerId(customer);c.setRequestId(UUID.randomUUID().toString());c.setSubject("Request");c.setDescription("Description");em.persist(c);}em.getTransaction().commit();String jpql=ClientCaseRepository.class.getMethod("search",Long.class,String.class,Pageable.class).getAnnotation(Query.class).value();assertEquals(1,em.createQuery(jpql,ClientCase.class).setParameter("customer",acme.getId()).setParameter("status","OPEN").getResultList().size());assertEquals(2,em.createQuery(jpql,ClientCase.class).setParameter("customer",null).setParameter("status",null).getResultList().size());}
}
